    <section class="parity-panel" id="parity-workflow" role="tabpanel" data-parity-panel="workflow" hidden><div class="parity-section-head"><div><h2>End-to-end workflow</h2><p>Every operation moves through predictable validation, execution and evidence.</p></div></div><div class="parity-workflow">${config.workflow.map((item,index)=>`<div class="parity-step"><div class="parity-step-num">${index+1}</div><strong>${item[0]}</strong><span>${item[1]}</span></div>`).join("")}</div></section>
